def read_new_messages() -> list[dict]:
    """Lee mensajes nuevos del canal web_chat."""
    sources = [WILLIAM_CHANNEL]
    # También monitorear mensajes del equipo
    for extra in [DIR / "ada_messages.jsonl", DIR / "jarvis_messages.jsonl"]:
        if extra.exists():
            sources.append(extra)

    # Usar solo william_channel para determinar posición del counter
    if not WILLIAM_CHANNEL.exists():
        return []

    lines = WILLIAM_CHANNEL.read_text(encoding="utf-8").splitlines()
    total = len(lines)
    last = int(COUNTER_FILE.read_text().strip()) if COUNTER_FILE.exists() else 0

    if total <= last:
        return []

    new = []
    for line in lines[last:]:
        line = line.strip()
        if not line:
            continue
        try:
            msg = json.loads(line)
            if msg.get("from", "").lower() in ("william",):
                new.append(msg)
        except Exception:
            pass

    COUNTER_FILE.write_text(str(total))
    return new

